package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="rsp_hrmpsb_attendance") public class HrmpsbAttendance extends RspAuditedEntity{
 public enum Status{PRESENT,ABSENT,EXCUSED,RECUSED}@Column(name="meeting_id",nullable=false,length=36)private String meetingId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Column(name="member_role",nullable=false,length=30)private String memberRole;@Enumerated(EnumType.STRING)@Column(name="attendance_status",nullable=false,length=20)private Status status;@Column(name="voting_eligible",nullable=false)private boolean votingEligible;@Column(name="recorded_by",nullable=false,length=100)private String recordedBy;@Column(name="recorded_at",nullable=false)private Instant recordedAt;@Column(length=1000)private String remarks;
 protected HrmpsbAttendance(){}public HrmpsbAttendance(String agency,String meeting,String employee,String role,Status status,boolean voting,String actor,Instant at,String remarks){super(agency);meetingId=requiredText(meeting,"meetingId");employeeNo=requiredText(employee,"employeeNo");memberRole=requiredText(role,"memberRole");this.status=Objects.requireNonNull(status);votingEligible=voting&&status==Status.PRESENT;recordedBy=requiredText(actor,"actor");recordedAt=Objects.requireNonNull(at);this.remarks=optionalText(remarks);}public String getMeetingId(){return meetingId;}public String getEmployeeNo(){return employeeNo;}public String getMemberRole(){return memberRole;}public Status getStatus(){return status;}public boolean isVotingEligible(){return votingEligible;}
}
